/**
 * 判断组件标识（可精确到版本）是否在 web/h5 区分灰度白名单内
 * 白名单条目支持两种格式：
 *   1. 纯组件标识，如 testdata          —— 匹配该组件所有版本
 *   2. 组件标识:版本号，如 testdata:30.0.0 —— 匹配该组件指定版本
 * 白名单为空则全部返回 false（功能关闭，走存量逻辑）
 *
 * @param componentIdentification 组件标识
 * @param componentVersion        组件版本
 * @return true=白名单内，启用新功能；false=走存量逻辑
 * */
private boolean isInWhitelist(String componentIdentification, String componentVersion) {
    if (StrUtil.isBlank(componentIdentification)) {
        return false;
    }
    if (CollectionUtils.isEmpty(menuWebH5GroupWhitelist)) {
        return false;
    }
    String componentId = componentIdentification.trim();
    for (String item : menuWebH5GroupWhitelist) {
        if (StrUtil.isBlank(item)) {
            continue;
        }
        String trimItem = item.trim();
        //不带冒号：整组件配置，组件标识相等即命中
        if (!trimItem.contains(":")) {
            if (componentId.equals(trimItem)) {
                return true;
            }
            continue;
        }
        //带冒号：组件标识:版本号，需组件和版本都精确匹配
        String[] arr = trimItem.split(":");
        if (arr.length == 2 && componentId.equals(arr[0].trim()) && componentVersion != null && componentVersion.trim().equals(arr[1].trim())) {
            return true;
        }
    }
    return false;
}

/**
 * 判断组件版本是否启用 web/h5 菜单区分：
 * 1. 先判灰度白名单（纯内存判断），未命中直接 false，不产生远程调用
 * 2. 白名单命中后再查 model_dev_db 的 component_version_info.c_framework_type，仅 web 类型启用区分，其余类型走存量逻辑
 * 3. framework_type 查询失败或为空时按不启用处理（fail-safe 回存量逻辑），不阻断菜单查询
 *
 * @param componentIdentification 组件标识
 * @param componentVersion        组件版本
 * @return true=启用 web/h5 区分；false=走存量逻辑
 * */
private boolean isWebH5GroupEnabled(String componentIdentification, String componentVersion) {
    if (!isInWhitelist(componentIdentification, componentVersion)) {
        return false;
    }
    try {
        Map<String, Object> versionInfo = componentModelClient.queryDevComponentVersionInfo(componentIdentification, componentVersion);
        if (MapUtils.isEmpty(versionInfo) || versionInfo.get("c_framework_type") == null) {
            logger.info("isWebH5GroupEnabled framework_type empty, fallback legacy. componentIdentification:{} componentVersion:{}",
                    componentIdentification, componentVersion);
            return false;
        }
        boolean enabled = FRAMEWORK_TYPE_WEB.equals(String.valueOf(versionInfo.get("c_framework_type")).trim());
        logger.info("isWebH5GroupEnabled result:{}, componentIdentification:{} componentVersion:{} frameworkType:{}",
                enabled, componentIdentification, componentVersion, versionInfo.get("c_framework_type"));
        return enabled;
    } catch (Exception e) {
        logger.error("isWebH5GroupEnabled query component_version_info fail, fallback legacy. componentIdentification:{} componentVersion:{}",
                componentIdentification, componentVersion, e);
        return false;
    }
}
